'use strict';
const railTabs=[['environment','环境','SCENE ENVIRONMENT','环境设置'],['resource','资源','ASSET LIBRARY','资源库'],['layers','图层','SCENE HIERARCHY','场景对象'],['traffic','交通','TRAFFIC SIMULATION','交通仿真'],['tour','导览','CAMERA SEQUENCER','导览编排']];
const act=(id,title,cls='',icon='')=>'<button type="button" data-act="'+esc(id)+'" class="'+cls+'">'+(icon?ic(icon):'')+esc(title)+'</button>';
const head=(title,icon='',meta='')=>'<div class="sectionHead"><h3>'+(icon?'<i>'+ic(icon)+'</i>':'')+esc(title)+'</h3>'+meta+'</div>';
const range=(name,label,value,min,max,step=1,unit='',percent=false)=>'<div class="control"><div class="row"><label for="r-'+name+'">'+esc(label)+'</label><output data-out="'+name+'">'+(percent?Math.round(value*100):Number(value.toFixed(2)))+esc(unit)+'</output></div><input id="r-'+name+'" data-range="'+name+'" data-unit="'+esc(unit)+'" data-pct="'+(percent?1:0)+'" type="range" min="'+min+'" max="'+max+'" step="'+step+'" value="'+value+'" style="--p:'+((value-min)/(max-min)*100)+'%"></div>';
const field=(key,label,val,type='text',extra='')=>'<label class="field">'+esc(label)+'<input data-field="'+key+'" type="'+type+'" value="'+esc(val)+'" '+extra+'></label>';
const tog=(key,txt,on)=>'<div class="row gap"><span>'+esc(txt)+'</span><button class="switch" role="switch" aria-label="'+esc(txt)+'" aria-checked="'+!!on+'" data-act="'+key+'"></button></div>';
const sel=(key,label,items,value)=>'<label class="field">'+esc(label)+'<select data-field="'+esc(key)+'">'+items.map(([v,n])=>'<option value="'+esc(v)+'" '+(String(value)===String(v)?'selected':'')+'>'+esc(n)+'</option>').join('')+'</select></label>';
const groupOptions=['prop','plant','material','vehicle','character','effect','marker','water'];
let filterEdited=false,layerGroupIds=[],multiIds=[],lastMaterial=null,thumbRenderer,thumbCanvas,thumbSignature=null,renderToken=0;
function renderRail(){$('#railItems').innerHTML=railTabs.map(([key,title])=>'<button class="railBtn '+(section===key?'active':'')+'" data-tab="'+key+'" title="'+title+'" aria-pressed="'+(section===key)+'">'+ic(key)+'<span>'+title+'</span></button>').join('');}
function selectSection(s){if(playing)stopPlay();cancelDrawing();section=s;panelMode='';renderRail();renderPanel();dirty=true;}
function renderEnv(){const e=S.env;return '<div class="section">'+head('天气模拟','cloud','<span class="meta">WEATHER</span>')+'<div class="weatherGrid">'+Object.entries(weatherTypes).map(([k,[n,i]])=>'<button class="weather '+(e.weather===k?'on':'')+'" data-act="weather:'+k+'" aria-pressed="'+(e.weather===k)+'">'+ic(i)+'<span>'+n+'</span></button>').join('')+'</div>'+(e.weather==='rain'||e.weather==='snow'?range('env.intensity','降'+(e.weather==='rain'?'雨':'雪')+'强度',e.intensity,0,1,.01,'%',true):e.weather==='fog'?range('env.visibility','可见距离',e.visibility,50,3000,10,' m')+range('env.intensity','雾气浓度',e.intensity,0,1,.01,'%',true):e.weather==='cloud'?range('env.cloudDensity','云层密度',e.cloudDensity,0,1,.01,'%',true)+range('env.cloudHeight','云层高度',e.cloudHeight,100,4000,50,' m'):'')+'</div><div class="section">'+head('场景时间','clock','<span class="meta">24 H</span>')+'<div class="timeFace"><div><div id="timeBig" class="timeBig">'+fmtTime(e.time)+'</div><small class="timeZone">UTC '+(e.utc>=0?'+':'')+e.utc+'</small></div><span id="sunTag" class="sunTag">'+envTag(e.time)+'</span></div><svg class="arc" viewBox="0 0 240 33" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="sunFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#dcb17b" stop-opacity=".20"/><stop offset="1" stop-color="#dcb17b" stop-opacity="0"/></linearGradient></defs><path d="M0 31 Q120 -22 240 31Z" fill="url(#sunFill)"/><path d="M0 31 Q120 -22 240 31" stroke="#a38d69" fill="none" stroke-width="1" stroke-dasharray="3 3"/><circle id="sunDot" r="4" fill="#efbe80"/></svg><input aria-label="场景时间" type="range" min="0" max="23.9833" step=".0166667" value="'+e.time+'" id="timeSlider" data-range="env.time" style="--p:'+e.time/24*100+'%"><div class="ticks"><span>00:00</span><span>06:00</span><span>12:00</span><span>18:00</span><span>24:00</span></div><div class="timePresets">'+[[6,'清晨'],[12,'正午'],[18,'黄昏'],[0,'午夜']].map(([t,n])=>act('time:'+t,n,e.time===t?'on':'')).join('')+'</div>'+tog('cycle','昼夜循环',e.cycle)+(e.cycle?range('env.cycleSeconds','循环时长',e.cycleSeconds,10,600,5,' s'):'')+'</div><div class="section">'+head('环境光照','sun','<span class="meta">LIGHTING</span>')+range('env.solarPower','太阳光强度',e.solarPower,0,2,.01,'%',true)+range('env.skyLight','天空光强度',e.skyLight,.15,2,.01,'%',true)+'</div><details class="section"><summary>地理位置与高级参数</summary><div class="inputs">'+field('env.lat','纬度 °',e.lat,'number','min="-89" max="89" step=".01"')+field('env.lon','经度 °',e.lon,'number','min="-180" max="180" step=".01"')+field('env.utc','时区 UTC',e.utc,'number','min="-12" max="14"')+field('env.day','年内第几天',e.day,'number','min="1" max="365"')+'</div>'+range('env.lunarPower','月光强度',e.lunarPower,.1,2,.01,'%',true)+tog('labels','显示空间标记文字',e.labels)+'</details><div class="panelFoot">'+ic('globe')+'<div>滨水科创园<small>'+Math.abs(e.lat).toFixed(2)+'° '+(e.lat>=0?'N':'S')+' &nbsp; '+Math.abs(e.lon).toFixed(2)+'° '+(e.lon>=0?'E':'W')+'</small></div></div>';}
function updateTimeUI(){const e=S.env,p=e.time/24;let a=$('#timeBig');if(!a)return;a.textContent=fmtTime(e.time);$('#timeSlider').value=e.time;$('#timeSlider').style.setProperty('--p',100*p+'%');$('#sunTag').textContent=envTag(e.time);$('#sunDot').setAttribute('cx',240*p);$('#sunDot').setAttribute('cy',31-106*p*(1-p));}
function current(){return S.objects.find(o=>o.id===selected);}
function resourcePanel(){const list=assets.filter(a=>a.group===assetGroup),families=Array.from(new Set(list.map(a=>a.family))),filtered=list.filter(a=>(!family||a.family===family)&&(!filterEdited||S.edited.includes(a.id))&&(!search||[a.name,a.family].join(' ').includes(search)));page=cap(page,0,Math.max(0,Math.ceil(filtered.length/8)-1));const items=filtered.slice(page*8,page*8+8);
return '<div class="tabWrap">'+groupOptions.map(k=>act('ag:'+k,groupName[k],'pill '+(assetGroup===k?'on':''))).join('')+'</div><div class="searchBox">'+ic('search')+'<input data-search="asset" value="'+esc(search)+'" placeholder="按名称搜索资源" aria-label="搜索资源"></div>'+sel('family','资源分类',[['','全部分类'],...families.map(f=>[f,f])],family)+(assetGroup==='material'?'<div class="buttons gap">'+act('edited',filterEdited?'显示全部材质':'已编辑材质')+act('pickmat','场景拾取')+'</div>':'')+'<div class="pager"><span>'+filtered.length+' 项'+(filtered.length?' · '+(page+1)+'/'+Math.ceil(filtered.length/8):'')+'</span><span>'+act('page:-1','上一页','mini')+act('page:1','下一页','mini')+'</span></div><div class="assetGrid">'+items.map(a=>'<button class="asset '+(a.id===activeAsset?'on':'')+'" draggable="true" data-asset="'+esc(a.id)+'" title="'+esc(a.name)+'">'+(a.group==='material'?'<div class="swatch"><b style="background:radial-gradient(circle at 29% 24%,#f4f6ed,'+safeColor(a.color)+' 40%,#17292c 94%)"></b></div>':'<canvas data-thumb="'+esc(a.id)+'" width="142" height="75"></canvas>')+'<span>'+esc(a.name)+'</span></button>').join('')+'</div>'+(!items.length?'<div class="empty">当前筛选下没有资源</div>':'')+'<div class="smallNote">'+(assetGroup==='material'?'拖到模型上替换材质，或先选模型再点材质。':'点击资源后在视口放置，也可直接拖入场景。')+'</div>'+(assetGroup==='plant'?plantTools():'')+(assetGroup==='material'&&activeAsset?matTools():'')+'<div class="section">'+head('扩充资源','plus')+'<div class="buttons">'+act('importAsset','导入 OBJ / JSON')+act('saveAsset','另存预设')+act('assetOut','导出资源 JSON')+'</div></div>';}
function safeColor(c){return /^#[a-f\d]{6}$/i.test(c)?c:'#7ba39c';}
function plantTools(){return '<div class="section">'+head('植被绘制','leaf')+'<div class="buttons">'+[['place','点插入'],['brush','混合笔刷'],['spline','样条路径'],['erase','擦除'],['lasso','套索选择']].map(([a,n])=>act('draw:'+a,n,drawing?.type===a?'on':'')).join('')+'</div>'+range('brush.radius','笔刷半径',brush.radius,1,20,1,' m')+range('brush.density','每笔株数',brush.density,1,15,1,' 株')+range('brush.spacing','路径间距',brush.spacing,1,15,.5,' m')+'<div class="inputs">'+field('brush.min','随机比例下限',brush.min,'number','step=".05" min=".1" max="4"')+field('brush.max','随机比例上限',brush.max,'number','step=".05" min=".1" max="4"')+'</div>'+tog('eraseAll','擦除所有植被类型',brush.all)+'<div class="buttons">'+act('brushMix','加入混合笔刷（'+brush.mix.length+'）')+act('clearMix','清空混合种类')+'</div></div>';}
function matTools(){const a=assetMap.get(activeAsset);if(!a||a.group!=='material')return '';const refs=S.objects.filter(o=>o.mat===a.id);return '<div class="section">'+head('材质操作','sliders')+'<div class="muted">'+esc(a.name)+' · '+refs.length+' 个对象引用</div><div class="buttons">'+act('copyMat','复制')+act('renameMat','重命名')+act('showRefs','查看引用')+'</div></div>';}
function objectPanel(){const o=current();if(!o)return '';const a=resolved(o);return '<div class="section">'+head('对象属性','sliders',act('clearSel','取消选择','mini'))+field('obj.name','对象名称',o.name)+'<div class="inputs three">'+['x','y','z'].map(k=>field('obj.'+k,k.toUpperCase()+' / m',o[k],'number','step=".25"')).join('')+'</div>'+range('obj.scale','整体缩放',o.scale||1,.05,5,.05,' ×')+range('obj.ry','旋转角度',o.ry||0,-180,180,1,'°')+(o.mat?'<div class="smallNote">材质 · '+esc(assetMap.get(o.mat)?.name)+'</div>':'')+field('obj.tint','对象主色',a.material?.color||a.color||a.parts.find(x=>x.role==='body')?.color||a.parts[0]?.color||'#8aada5','color')+
(o.mat?range('mat.roughness','材质粗糙度',a.material.roughness??.5,0,1,.01)+range('mat.metalness','金属度',a.material.metalness??0,0,1,.01)+range('mat.opacity','透明度（不透明占比）',a.material.opacity??1,.05,1,.01)+range('mat.emissive','自发光',a.material.emissive??0,0,1,.01):'')+
(['marker','effect','character'].includes(o.group)?'<div class="inputs">'+field('obj.near','最近可见距离 m',o.near??0,'number','min="0"')+field('obj.far','最远可见距离 m',o.far??600,'number','min="1"')+'</div>':'')+
(o.group==='water'?range('obj.waveAmp','波纹幅度',o.waveAmp??1,.1,3,.1,' ×')+range('obj.waveSpeed','水面流速',o.waveSpeed??1,.1,4,.1,' ×'):'')+(o.group==='effect'?range('obj.range','粒子影响范围',o.range||1,.2,5,.1,' ×'):'')+(o.group==='plant'?field('obj.lodTint','远景植被色',o.lodTint||o.tint||'#779480','color'):'')+
(o.group==='marker'?tog('showText','显示标记文字',o.showText!==false)+tog('faceScreen','文字面向屏幕',o.faceScreen!==false)+range('obj.textAngle','文字旋转',o.textAngle||0,-180,180,1,'°')+range('obj.textScale','文字缩放',o.textScale||1,.25,3,.05,' ×')+field('obj.text','标记内容',o.text||o.name)+range('obj.fontSize','文字大小',o.fontSize||12,8,32,1,' px')+sel('obj.font','字体',[['system-ui','无衬线'],['serif','衬线'],['monospace','等宽']],o.font||'system-ui')+'<div class="inputs">'+field('obj.textColor','文字颜色',o.textColor||'#e5f4ed','color')+field('obj.outlineColor','轮廓颜色',o.outlineColor||'#14272c','color')+'</div>'+range('obj.outlineWidth','轮廓宽度',o.outlineWidth||0,0,5,.25,' px')+'<div class="inputs three">'+['X','Y','Z'].map(k=>field('obj.text'+k,'文字 '+k,o['text'+k]||0,'number','step=".1"')).join('')+'</div>':'')+'<div class="buttons">'+act('focusObj','定位')+act('dupeObj','复制')+act('deleteObj','删除','danger')+'</div></div>';}
function layersPanel(){let list=S.objects.filter(o=>(!layerFilter||o.group===layerFilter)&&(!layerSearch||o.name.includes(layerSearch)));return objectPanel()+(multiIds.length?'<div class="section">'+head('套索选中 '+multiIds.length+' 株','leaf')+'<div class="inputs">'+field('multi.x','横向平移 m',0,'number')+field('multi.z','纵向平移 m',0,'number')+'</div><div class="buttons">'+act('moveMulti','应用平移')+act('delMulti','删除选中植株','danger')+'</div></div>':'')+'<div class="section">'+head('对象列表','layers','<span class="meta">'+list.length+'</span>')+sel('layerFilter','图层分类',[['','全部分类'],...Array.from(new Set(S.objects.map(o=>o.group))).map(k=>[k,groupName[k]||k])],layerFilter)+'<div class="searchBox">'+ic('search')+'<input data-search="layer" value="'+esc(layerSearch)+'" placeholder="搜索场景对象" aria-label="搜索场景对象"></div><div class="buttons gap">'+act('hideGroup','隐藏本组')+act('showGroup','显示本组')+'</div><div class="sceneList">'+list.map(o=>'<div class="itemRow '+(selected===o.id?'current':'')+'">'+act('obj:'+o.id,o.name,'',o.group==='plant'?'leaf':'cube')+'<button data-act="visible:'+esc(o.id)+'" aria-label="'+(o.visible===false?'显示':'隐藏')+'">'+ic(o.visible===false?'hidden':'eye')+'</button></div>').join('')+'</div></div>';}
function trafficPanel(){const r=S.route,selectedModels=r.models.map(id=>assetMap.get(id)).filter(Boolean);return '<div class="section">'+head('行驶路线','road')+field('route.name','路线名称',r.name)+'<div class="row"><span>'+r.points.length+' 个路径节点</span><span class="meta">'+getRouteSegments(r).sum.toFixed(0)+' m</span></div><div class="buttons">'+act('routeDraw','重绘路径')+act('routeEdit','编辑节点')+'</div>'+tog('closed','首尾闭合',r.closed)+tog('run','车辆运行',r.run)+'</div><div class="section">'+head('道路与车流','sliders')+range('route.speed','行驶速度',r.speed,1,100,1,' km/h')+range('route.density','车辆数量',r.density,1,24,1,' 辆')+range('route.lanes','单向车道',r.lanes,1,4,1,' 条')+range('route.width','车道宽度',r.width,1.5,6,.1,' m')+tog('both','双向车道',r.both)+tog('reverse','反向行驶',r.reverse)+'</div><div class="section">'+head('车辆列表','traffic','<span class="meta">'+r.models.length+' 类</span>')+selectedModels.map(a=>'<div class="itemRow">'+act('model:'+a.id,a.name)+'<button data-act="removeModel:'+esc(a.id)+'" aria-label="移除车辆">'+ic('x')+'</button></div>').join('')+sel('newModel','添加车型',[['','选择车型'],...assets.filter(a=>a.group==='vehicle'&&!r.models.includes(a.id)).map(a=>[a.id,a.name])],'')+'<div class="buttons">'+act('clearVehicles','清空车辆列表')+'</div></div>';}
function tourPanel(){let f=S.frames.find(a=>a.id===frameId);return '<div class="section">'+field('tourName','导览名称',S.tourName)+'<div class="row"><span>'+S.frames.length+' 个关键帧</span><span class="meta">'+duration()+' s</span></div><div class="buttons">'+act('addFrame','记录当前镜头','','plus')+act('play','播放导览','','play')+'</div></div>'+(f?'<div class="section">'+head('关键帧设置','camera')+field('frame.name','关键帧名称',f.name)+range('frame.duration','转场 / 停留时长',f.duration,1,30,.5,' s')+'<div class="muted">'+fmtTime(f.env.time)+' · '+weatherTypes[f.env.weather][0]+' · '+f.hidden.length+' 个隐藏对象</div><div class="buttons">'+act('replaceFrame','以当前视口覆盖')+act('prevFrame','前移')+act('nextFrame','后移')+act('deleteFrame','删除','danger')+'</div></div>':'')+'<div class="section">'+head('输出','export')+'<div class="smallNote">视频包含场景画面、天气、车辆和可见标记。支持 720p、1080p、4K。</div>'+act('export','导出导览视频','primary gap','export')+'</div>';}
function renderPanel(){const tab=railTabs.find(a=>a[0]===section);$('#panelCategory').textContent=tab[2];$('#panel').innerHTML='<h2 class="panelTitle">'+tab[3]+'</h2>'+({environment:renderEnv,resource:resourcePanel,layers:layersPanel,traffic:trafficPanel,tour:tourPanel}[section])();if(section==='environment')updateTimeUI();if(section==='resource'){for(const c of $$('canvas[data-thumb]')){let a=assetMap.get(c.dataset.thumb);if(a)Twin3D.thumbnail(c,a);}}}
function duration(){return S.frames.reduce((s,f)=>s+f.duration,0);}
function highlight(i){$$('.frameCard').forEach((c,k)=>c.classList.toggle('on',k===i));}
function renderStory(){const holder=$('#frameList'),pos=holder.scrollLeft;$('#storyMeta').textContent=S.frames.length+' 帧 / '+duration()+' s';holder.innerHTML=S.frames.length?S.frames.map((f,i)=>'<button class="frameCard '+(f.id===frameId?'on':'')+'" data-frame="'+esc(f.id)+'" title="'+esc(f.name)+'"><canvas width="256" height="82"></canvas><b class="frameNum">'+String(i+1).padStart(2,'0')+'</b><div class="frameCap"><span>'+esc(f.name)+'</span><small>'+f.duration+' s</small></div></button>').join(''):'<div class="empty">调整场景镜头，点击“添加关键帧”开始导览。</div>';holder.scrollLeft=pos;clearTimeout(thumbTimer);let token=++renderToken;thumbTimer=setTimeout(()=>drawThumbs(token),80);}
function drawThumbs(token){if(token!==renderToken||exporting)return;if(!thumbCanvas){thumbCanvas=document.createElement('canvas');thumbCanvas.width=256;thumbCanvas.height=82;thumbRenderer=Twin3D.renderer(thumbCanvas);}let cards=$$('.frameCard canvas'),i=0;function step(){if(token!==renderToken||exporting||i>=cards.length)return;const f=S.frames[i],sig=JSON.stringify([S.objects,f.hidden]);if(sig!==thumbSignature){thumbSignature=sig;thumbRenderer.set(S.objects.filter(o=>!f.hidden.includes(o.id)).map(o=>({...resolved(o),visible:true})));}thumbRenderer.render({...f.cam,span:f.cam.span*.77},f.env,2,[]);cards[i].getContext('2d').drawImage(thumbCanvas,0,0);i++;setTimeout(step,8);}step();}
function renderAll(){renderRail();renderPanel();renderStory();updateStatus();undoBtns();$('#viewName').textContent=viewLabel();}
function viewLabel(){return S.cam.pitch>83?'俯视视图': Math.abs(S.cam.yaw-home.yaw)<.1&&Math.abs(S.cam.pitch-home.pitch)<.1?'轴测视图':'自由视图';}
function setTool(t){tool=t;$$('[data-tool]').forEach(e=>e.classList.toggle('on',e.dataset.tool===t));}
function hint(){const box=$('#overHint');if(!drawing){box.hidden=true;world.style.cursor='';return;}world.style.cursor='crosshair';const text={place:'单击场景放置资源',material:'单击模型应用材质',pick:'单击模型拾取材质',brush:'按住并移动绘制植被',erase:'按住并移动擦除植被',spline:'逐点绘制植被路径',traffic:'逐点绘制车辆路线',lasso:'按住并圈选植株'}[drawing.type];box.hidden=false;box.innerHTML=text+(drawing.points?' · '+drawing.points.length+' 点 '+act('finish','完成'):'')+' '+act('cancel','退出');updateStatus();}
function cancelDrawing(){drawing=null;hint();dirty=true;updateStatus();}
function startDraw(type,asset=activeAsset){if(playing)stopPlay();if(['place','brush','spline','material'].includes(type)&&!assetMap.has(asset)){toast('请先选择一种资源');return;}drawing={type,asset,...(['spline','traffic'].includes(type)?{points:[]}:{})};hint();dirty=true;}
